  "bots.setup.callbackUrlDescription.webhook":
    "سیستم خارجی شما باید فراخوانی‌های برگشتی پیام‌های ورودی را به این نشانی بفرستد. پاسخ‌های خروجی غیرهمزمان همچنان از URL وب‌هوک واردشده در سمت چپ استفاده می‌کنند.",
