  "settings.httpProxy": "پروکسی HTTP",
  "settings.httpProxyDescription":
    "ترافیک خروجی مدل، MCP، ابزارهای دستوری و رندرکننده برنامه از طریق این پروکسی مسیریابی می‌شود؛ متغیرهای محیطی سیستم خوانده نمی‌شوند. اگر خالی بگذارید این ترافیک مستقیم متصل می‌شود، اما مرورگر تعبیه‌شده از تنظیمات پروکسی سیستم شما پیروی می‌کند. برای اعمال، برنامه را دوباره راه‌اندازی کنید.",
  "settings.httpProxyPlaceholder":
    "خالی یعنی مرورگر تعبیه‌شده از پروکسی سیستم پیروی می‌کند، مثلاً http://127.0.0.1:7890",
  "settings.httpProxyNoProxy": "بدون پروکسی",
  "settings.httpProxyNoProxyDescription":
    "درخواست‌های منطبق با این میزبان‌ها به‌جای استفاده از پروکسی HTTP مستقیم متصل می‌شوند. قواعد را با کاما جدا کنید. برای اعمال، برنامه را دوباره راه‌اندازی کنید.",
  "settings.httpProxyNoProxyPlaceholder": "مثلاً localhost,127.0.0.1,::1,.example.com,*.corp.com",
  "settings.httpProxyCaCertPath": "گواهی سفارشی",
  "settings.httpProxyCaCertPathDescription":
    "اختیاری. مسیر گواهی ریشه PEM را تعیین کنید تا به‌عنوان NODE_EXTRA_CA_CERTS برای مدل‌ها، MCP و ابزارهای دستوری تزریق شود و در تأیید گواهی رندرکننده مورد اعتماد قرار گیرد. برای اعمال، برنامه را دوباره راه‌اندازی کنید.",
  "settings.httpProxyCaCertPathPlaceholder": "مثلاً /Users/name/certs/root-ca.pem",
  "settings.httpProxySavedHint":
    "تنظیمات پروکسی شبکه ذخیره شد. برای اعمال، برنامه را دوباره راه‌اندازی کنید.",
  "settings.desktopChromiumHardwareAcceleration": "شتاب‌دهی سخت‌افزاری Chrome",
  "settings.desktopChromiumHardwareAccelerationDescription":
    "برای رفع پنجره‌های خالی، خرابی‌ها یا مشکلات رندر ناشی از برخی GPUها یا درایورها، این گزینه را خاموش کنید. برای اعمال، برنامه را دوباره راه‌اندازی کنید.",
