  "settings.modelProvider.fieldHelp": "درباره {field}",
  "settings.modelProvider.help.contextWindow":
    "ظرفیت زمینه‌ای که مدل می‌تواند در هر لحظه پردازش کند، بر حسب توکن. ZCodium از این مقدار برای مدیریت زمینه استفاده می‌کند.\nاز حد واقعی مدل فراتر نروید.",
  "settings.modelProvider.help.maxOutputTokens":
    "حداکثر تعداد توکنی که یک درخواست از مدل می‌تواند تولید کند.\nاز حد واقعی مدل فراتر نروید.",
  "settings.modelProvider.help.inputModalities":
    "انواع محتوایی که مدل می‌تواند دریافت کند را تنظیم کنید:\n\n- **متن**: محتوای متنی دریافت می‌کند. الزامی است.\n- **تصویر**: محتوای تصویری دریافت می‌کند.\n- **ویدیو**: محتوای ویدیویی دریافت می‌کند.\n- **PDF**: اسناد PDF را مستقیماً دریافت می‌کند.",
  "settings.modelProvider.help.outputModalities":
    "نوع محتوای پاسخ‌های مدل. در حال حاضر فقط متن پشتیبانی می‌شود.",
  "settings.modelProvider.help.capabilities":
    "- **خروجی ساختاریافته**: پشتیبانی از محدودیت‌های JSON Schema روی فیلدها، انواع و ساختار خروجی.\n- **جست‌وجوی وب بومی**: پشتیبانی از قابلیت جست‌وجوی وب داخلی API مدل.\n- **پیام‌های سیستمی میانه گفتگو**: پشتیبانی از درج دستورالعمل‌های سیستمی در میانه گفتگو.\n\nقابلیت‌هایی را که مدل از آن‌ها پشتیبانی نمی‌کند فعال نکنید.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "سطوح تفکری را که در گفتگو در دسترس هستند تنظیم کنید. **باید از کمترین تا بیشترین میزان تفکر مرتب شده باشند**.\nسطوح تفکری را که مدل از آن‌ها پشتیبانی نمی‌کند پیکربندی نکنید.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "برای نگاشت سطح تفکر فعلی، یعنی `reasoningLevel`، به فیلدهای درخواست API مدل از یک عبارت CEL استفاده کنید. شیء JSON بازگردانده‌شده توسط این عبارت در بدنه درخواست خروجی ادغام می‌شود.",
  "settings.modelProvider.help.advanced":
    "**MFJS tool schema**: سازگاری با Moonshot Flavored JSON Schema را فعال می‌کند که معمولاً در API مدل Kimi شرکت Moonshot استفاده می‌شود. تنها زمانی فعال کنید که API مدل به این قالب نیاز داشته باشد.",
  "settings.modelProvider.help.followRecommendedConfig":
    "بر اساس شناسه مدل، Base URL و قالب API با پیکربندی پیشنهادی مطابقت می‌دهد. ZCodium پیشنهادها را مداوم به‌روزرسانی می‌کند و به‌طور خودکار برای شما همگام‌سازی می‌کند.\nهر تنظیمی را که به‌صورت دستی تغییر دهید، به مدیریت دستی درمی‌آید و دیگر پیشنهادها را دنبال نمی‌کند؛ سایر تنظیمات تحت مدیریت پیکربندی هوشمند باقی می‌مانند.",
